import { Component, OnDestroy, OnInit, ViewChild } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { toBoolean, Utils } from '@rsApp/modules/utils/providers/utils';
import { NavController } from '@ionic/angular';
import { Subject, firstValueFrom, tap, takeUntil } from 'rxjs';
import { CurrentStore } from '@rsApp/modules/store/store.module';
import { escape, each, filter } from 'lodash';
import { AppSettings } from '@rsApp/modules/utils/providers/app-setting';
import { IMagRecipe } from '../../model/interface';
import { RecipeService } from '../../providers/recipe.service';
import { DxpComponentService } from '@rsApp/modules/utils/providers/dxp.component.service';
import { Credential } from '@rsApp/modules/auth-v2/providers/credential.service';
import { MagAppBottomSheetComponent } from '@rsApp/components/mag-app-bottom-sheet/mag-app-bottom-sheet';
import { ITenantSettings } from '@rsApp/modules/utils/models/app-settings.model';
import { TenantSettingsStore } from '@rsApp/modules/utils/providers/tenant-settings.service';
import { Capacitor } from '@capacitor/core';
import { Share } from '@capacitor/share';
@Component({
  selector: 'recipe-detail',
  templateUrl: 'recipe-detail.html',
  styleUrls: ['recipe-detail.scss'],
})
export class RecipeDetailPageComponent implements OnDestroy, OnInit {
  slug: string;
  isReadMore = true;
  hideReadMore = false;
  checkedCount = 0;
  isFavorite = false;
  loadingImageFailed = false;
  isAdjustUI: boolean = false;
  loaded: boolean = false;
  defaultRecipeImage: string;
  isNative: boolean = false;
  recipe: IMagRecipe;
  checkedIngredients: any[] = [];
  webSEOUrl: string;
  //dxp
  dxpGallery: string;
  dxpSavedRecipeBtn: string;
  dxpShareRecipeBtn: string;
  @ViewChild('bottomSheet', { static: false }) bottomSheetComponent!: MagAppBottomSheetComponent;
  @ViewChild('bottomSheetMail', { static: false }) bottomSheetMailComponent!: MagAppBottomSheetComponent;
  sharingOptions = [
    {
      type: 'email',
      actionText: 'Mail',
      icon: 'mail-outline',
    },
    {
      type: 'more',
      actionText: 'More',
      icon: 'ellipsis-horizontal-outline',
    },
  ];

  public tenantSettings: ITenantSettings;
  private _destroy$ = new Subject();
  constructor(
    public router: Router,
    public utils: Utils,
    public route: ActivatedRoute,
    public cStore: CurrentStore,
    public navCtrl: NavController,
    public appSettings: AppSettings,
    public recipeService: RecipeService,
    public dxpComponentService: DxpComponentService,
    public cre: Credential,
    private tenantSettingsStore: TenantSettingsStore
  ) {
    this.route.params.pipe(takeUntil(this._destroy$)).subscribe((param) => {
      this.slug = param?.slug || '';
    });
  }

  async ngOnInit() {
    this.isAdjustUI = toBoolean(await firstValueFrom(this.appSettings.getSettingValue('adjust_ui_temporary')));
    this.tenantSettings = await this.tenantSettingsStore.getTenantSettings();
  }

  ngOnDestroy() {
    this._destroy$.next(true);
    this._destroy$.complete();
  }

  async ionViewWillEnter() {
    try {
      await this.init();
    } catch (error) {
      console.error(error);
    }
  }

  ionViewDidEnter() {
    this.appSettings
      .getSettingValue('recipe_default_image_url')
      .pipe(
        takeUntil(this._destroy$),
        tap((val) => {
          this.defaultRecipeImage = val;
        })
      )
      .subscribe();
  }

  ionViewDidLeave() {
    this.dxpGallery = '';
    this.dxpSavedRecipeBtn = '';
    this.dxpShareRecipeBtn = '';
    this.webSEOUrl = '';
  }

  async init() {
    this.isNative = Capacitor.isNativePlatform();
    this.checkedCount = 0;
    this.loaded = false;
    this.recipe =
      this.slug &&
      (await firstValueFrom(this.recipeService.getRecipe({ userId: this.cre.currentUser?.UserId, Code: this.slug })));
    this.loaded = true;
    this.initUiFromDxp();
    this.hideReadMore = this.recipe?.Description?.En?.length < 250;
  }

  updateMagGallery(images): void {
    const imageStr = images?.map((img) => {
      return img?.CloudUrl;
    });
    this.dxpGallery = `<mag-gallery image-string='${escape(JSON.stringify(imageStr))}'></mag-gallery>`;
  }

  async initUiFromDxp() {
    const formatSavedRecipe = this.recipe && escape(JSON.stringify(this.recipe));
    const webRecipeSlug = this.utils.getSEOSlug(this.recipe?.Title?.En, this.recipe?.Code);
    const webSEOUrl = await this.utils.mappingWebSEOUrl('recipe', webRecipeSlug);
    this.webSEOUrl = webSEOUrl;
    this.dxpShareRecipeBtn = `<mag-share-button show-copy-button=${!!webSEOUrl} share-url=${webSEOUrl} item-id=${this.recipe?.Code} share-type=${'recipe'} is-show-label=${true} share-image-url=${this.recipe?.Images[0]?.CloudUrl}></mag-share-button>`;
    this.dxpSavedRecipeBtn = `<mag-recipe-favorite-button class="recipe-detail__save-action" recipe-str='${formatSavedRecipe}' is-show-label=${true} ></mag-recipe-favorite-button>`;
    this.updateMagGallery(this.recipe?.Images);
  }

  changeDesView() {
    this.isReadMore = !this.isReadMore;
  }

  public selectAll() {
    each(this.recipe?.Ingredients, (i) => {
      i.checked = true;
    });
    this.countCheckedItems();
  }
  public unselectAll() {
    each(this.recipe?.Ingredients, (i) => {
      i.checked = false;
    });
    this.countCheckedItems();
  }

  countCheckedItems() {
    this.checkedIngredients = filter(this.recipe?.Ingredients, { checked: true });
    this.checkedCount = this.checkedIngredients?.length;
  }

  async handleOption(actionType: string) {
    switch (actionType) {
      case 'email':
        this.bottomSheetMailComponent?.openModal();
        break;
      case 'more':
        await this.openNativeShare();
        break;
    }
  }

  openShare() {
    this.bottomSheetComponent?.openModal();
  }

  async openNativeShare() {
    try {
      await Share.share({
        text: this.webSEOUrl,
      });
    } catch (error) {
      console.warn(error, 'failed to share native');
    }
  }

  async closeShareModal() {
    this.bottomSheetMailComponent?.closeModal();
    this.bottomSheetComponent?.closeModal();
  }

  // Todo
  handlePrint() {
    window.print();
  }
}
