import { NgModule } from '@angular/core';
import { RouterModule, Routes } from '@angular/router';
import { RecipeModule } from './recipe.module';
import { RecipeListPageComponent } from './pages/recipe-list/recipe-list';
import { RecipeDetailPageComponent } from './pages/recipe-detail/recipe-detail';
import { RecipeListFavoritePageComponent } from './pages/recipe-list-favorite/recipe-list-favorite';

const baseRoute: Routes = [
  {
    path: '',
    redirectTo: 'browse',
    pathMatch: 'full',
  },
  {
    path: 'recipe-detail/:slug',
    component: RecipeDetailPageComponent,
  },
  {
    path: 'browse',
    component: RecipeListPageComponent,
    data: {
      routeName: 'browse',
    },
  },
  {
    path: 'favorites',
    component: RecipeListFavoritePageComponent,
    data: {
      routeName: 'favorites',
    },
  },
];

const routes = baseRoute.map((route) => ({
  ...route,
  data: {
    ...route.data,
    hideTab: true,
  },
}));

@NgModule({
  imports: [RouterModule.forChild(routes), RecipeModule],
  declarations: [],
})
export class RecipeRoutingModule {}
