import { Component, OnDestroy, OnInit } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { DxpComponentService } from '@rsApp/modules/utils/providers/dxp.component.service';
import { Subscription, concatMap } from 'rxjs';
import { RecipeService } from '../../providers/recipe.service';

@Component({
  selector: 'app-recipe-list',
  templateUrl: './recipe-list.html',
  styleUrls: ['./recipe-list.scss'],
})
export class RecipeListPageComponent implements OnInit, OnDestroy {
  public dxpRecipeList = '';
  public dxpFavoriteRecipeList = '';
  public queryParamsStr: string;
  public keyword = '';
  public onScreen: boolean = true;
  public onInit: boolean = true;
  public uns: Subscription;
  public eventListenerFn: any;

  constructor(
    public route: ActivatedRoute,
    public dxpComponentService: DxpComponentService,
    public recipeService: RecipeService,
    public router: Router
  ) {}

  async ngOnInit() {
    document.body.addEventListener('eventChangedParamsMagRecipe', this.updateQueryParams);
    await this.dxpComponentService.onConnected();
    this.onScreen = true;
  }

  updateQueryParams = (_e) => {
    this.router.navigate([], {
      queryParams: {
        keyword: _e.detail.kw,
        cats: _e.detail.cats,
        readyInIds: _e.detail.readyIns,
        pageIndex: _e.detail.pageIndex,
      },
    });
  };

  getParams(key: string, params) {
    const values = params?.[key]
      ? typeof params[key] === 'string'
        ? params[key].split(';')
        : Array.isArray(params[key])
          ? params[key]
          : [params[key]]
      : [];
    return values;
  }

  ionViewWillEnter() {
    this.uns = this.route.data
      .pipe(
        concatMap(() => {
          return this.route.queryParams;
        })
      )
      .subscribe((params) => {
        const cats = this.getParams('cats', params);
        const readyInIds = this.getParams('readyInIds', params);
        const queryParams = {
          categoryCodes: cats.length ? cats : null,
          pageIndex: params?.pageIndex || 1,
          readyInIds: readyInIds.length ? readyInIds : null,
        };
        if (this.onInit) {
          this.onInit = false;
          this.queryParamsStr = JSON.stringify(queryParams);
        }
        this.keyword = params?.keyword || '';
      });
  }

  ionViewWillLeave() {
    this.onInit = true;
    this.uns?.unsubscribe();
  }

  ngOnDestroy() {
    this.onScreen = false;
    document.body.removeEventListener('eventChangedParamsMagRecipe', this.updateQueryParams);
  }
}
